/// Resolve a UI catalog entry for [arabic] under an explicit language code.
///
/// Prefer [uiTr] in widgets. This pure helper is for tests and non-widget code.
String resolveUiTr(String arabic, {String languageCode = 'en'}) {
  final key = kArabicUiLookup[arabic];
  if (key == null) return arabic;
  final lang = languageCode.toLowerCase();
  final text = FFLocalizations(Locale(lang)).getText(key);
  return text.isNotEmpty ? text : arabic;
}

String uiTr(BuildContext context, String arabic) {
  final key = kArabicUiLookup[arabic];
  if (key == null) return arabic;
  // Two-arg Localizations.of returns null when the delegate is absent (tests).
  final ff = Localizations.of<FFLocalizations>(context, FFLocalizations);
  if (ff != null) {
    final text = ff.getText(key);
    if (text.isNotEmpty) return text;
  }
  // Tests / early frames without a localization delegate: deterministic EN.
  return resolveUiTr(arabic, languageCode: 'en');
}
